def solve(G):
    R,C = len(G), len(G[0])
    centers = []
    for r in range(R):
        for c in range(1,C-1):
            if G[r][c-1]==3 and G[r][c+1]==3 and ((r>0 and G[r-1][c]==3) or (r<R-1 and G[r+1][c]==3)):
                centers.append((r,c,G[r][c]))
    own = {(r,c):{(r,c),(r-1,c),(r+1,c),(r,c-1),(r,c+1)} for r,c,_ in centers}
    out = [row[:] for row in G]
    def paint(r, c, v, ownset):
        if not (0<=r<R and 0<=c<C): return False
        if (r,c) in ownset: return True
        if G[r][c] != 0: return False
        out[r][c] = v
        return True
    for r,c,v in centers:
        for cc in range(c-1,-1,-1):
            if not paint(r,cc,v,own[(r,c)]): break
        for cc in range(c+1,C):
            if not paint(r,cc,v,own[(r,c)]): break
    for r,c,v in centers:
        for rr in range(r-1,-1,-1):
            if not paint(rr,c,v,own[(r,c)]): break
        for rr in range(r+1,R):
            if not paint(rr,c,v,own[(r,c)]): break
    return out, centers

